  "Open a terminal in that folder and run": { es: "Abre una terminal en esa carpeta y ejecuta", ar: "افتح طرفية في ذلك المجلد وشغّل", zh: "在该文件夹中打开终端并运行", sw: "Fungua terminal kwenye folda hiyo na uendeshe", sv: "Öppna en terminal i mappen och kör" },
  ", then visit": { es: ", y luego visita", ar: "، ثم زر", zh: "，然后访问", sw: ", kisha tembelea", sv: ", och besök sedan" },
  ". (Double-clicking the file is not enough: the pages load shared files from the site root.)": { es: ". (No basta con hacer doble clic en el archivo: las páginas cargan archivos compartidos desde la raíz del sitio.)", ar: ". (النقر المزدوج على الملف لا يكفي: تحمّل الصفحات ملفات مشتركة من جذر الموقع.)", zh: "。（双击文件是不够的：页面会从网站根目录加载共享文件。）", sw: ". (Kubofya faili mara mbili haitoshi: kurasa hupakia faili za pamoja kutoka kwenye mzizi wa tovuti.)", sv: ". (Det räcker inte att dubbelklicka på filen: sidorna laddar delade filer från webbplatsens rot.)" },
  "The shared AI only answers requests from migabuilder.com, so on your copy choose": { es: "La IA compartida solo responde a peticiones de migabuilder.com, así que en tu copia elige", ar: "لا يجيب الذكاء الاصطناعي المشترك إلا على الطلبات القادمة من migabuilder.com، لذا اختر في نسختك", zh: "共享 AI 只响应来自 migabuilder.com 的请求，因此在你的副本中请选择", sw: "AI ya pamoja hujibu tu maombi kutoka migabuilder.com, kwa hivyo kwenye nakala yako chagua", sv: "Den delade AI:n svarar bara på förfrågningar från migabuilder.com, så i din kopia väljer du" },
  "and paste a key from the": { es: "y pega una clave de la", ar: "والصق مفتاحًا من", zh: "并粘贴从", sw: "na ubandike ufunguo kutoka kwa", sv: "och klistrar in en nyckel från" },
  "guide above": { es: "guía de arriba", ar: "الدليل أعلاه", zh: "上方指南", sw: "mwongozo hapo juu", sv: "guiden ovan" },
  ". The other AI tools have a": { es: ". Las demás herramientas de IA también tienen la opción", ar: ". لأدوات الذكاء الاصطناعي الأخرى خيار", zh: "获取的密钥。其他 AI 工具也有", sw: ". Zana nyingine za AI pia zina chaguo la", sv: ". De andra AI-verktygen har också alternativet" },
  "option too.": { es: ".", ar: "أيضًا.", zh: "选项。", sw: ".", sv: "." },
  "Want your own shared AI for your visitors, so they don’t need a key? Follow": { es: "¿Quieres tu propia IA compartida para tus visitantes, para que no necesiten clave? Sigue", ar: "تريد ذكاءً اصطناعيًا مشتركًا خاصًا بك لزوارك حتى لا يحتاجوا إلى مفتاح؟ اتبع", zh: "想为访客提供你自己的共享 AI，让他们无需密钥？请参照", sw: "Unataka AI yako ya pamoja kwa wageni wako, ili wasihitaji ufunguo? Fuata", sv: "Vill du ha en egen delad AI för dina besökare, så att de inte behöver någon nyckel? Följ" },
  "the Gemini proxy guide": { es: "la guía del proxy de Gemini", ar: "دليل وسيط Gemini", zh: "Gemini 代理指南", sw: "mwongozo wa proksi ya Gemini", sv: "guiden för Gemini-proxyn" },
  ": it keeps your key in a free Cloudflare Worker instead of the page.": { es: ": guarda tu clave en un Cloudflare Worker gratuito en lugar de en la página.", ar: ": يحفظ مفتاحك في Cloudflare Worker مجاني بدلًا من الصفحة.", zh: "：它会把你的密钥保存在免费的 Cloudflare Worker 中，而不是页面里。", sw: ": inahifadhi ufunguo wako kwenye Cloudflare Worker ya bure badala ya ukurasa.", sv: ": den håller din nyckel i en gratis Cloudflare Worker i stället för på sidan." },
  "💡 Tips for great pictures": { es: "💡 Consejos para imágenes geniales", ar: "💡 نصائح لصور رائعة", zh: "💡 好图片小贴士", sw: "💡 Vidokezo vya picha nzuri", sv: "💡 Tips för riktigt bra bilder" },
  "Say": { es: "Di", ar: "قل", zh: "说清楚", sw: "Sema", sv: "Ange" },
  "who or what": { es: "quién o qué", ar: "من أو ماذا", zh: "是谁或什么", sw: "nani au nini", sv: "vem eller vad" },
  "where": { es: "dónde", ar: "أين", zh: "在哪里", sw: "wapi", sv: "var" },
  "what is happening": { es: "qué está pasando", ar: "ماذا يحدث", zh: "发生了什么", sw: "nini kinatokea", sv: "vad som händer" },
